import {layoutHeader,layoutHero,layoutCollection,layoutCss} from './layouts.js';
import * as base from './engine.js';
import {safeUrl,richText,entryUrl,entryPath,slugFor,validateProject,createProject} from './project.js';
const esc=base.escapeHtml;
export {pageNames,escapeHtml,installGuide} from './engine.js';
function project(t,o,l='pl'){return o?.project?validateProject(o.project,t.id):createProject(t,l,o);}
function resolve(t,p){return {...t,bg:p.background,image:safeUrl(p.heroImage,true),headline:{pl:p.heroTitle,en:p.heroTitle},description:{pl:p.heroText,en:p.heroText},topic:{pl:p.heroLabel,en:p.heroLabel}};}
const options=p=>({brand:p.brand,email:p.email,accent:p.accent,font:p.font});
function css(p){return `:root{--paper:${p.background};--ink:${p.ink};--accent:${p.accent};--muted:color-mix(in srgb,var(--ink) 68%,var(--paper));--line:color-mix(in srgb,var(--ink) 18%,var(--paper))}body{font-size:${p.fontSize}px}.wrap{max-width:${p.width}px}.pill,.story img,.extra-section img{border-radius:${p.radius}px}.site-nav{flex-wrap:wrap}.prose,.extra-section{overflow-wrap:anywhere}.extra-section{padding:45px 0;border-top:1px solid var(--line)}.extra-section img{max-height:560px;margin:22px 0;object-fit:cover}.extra-section .pill{margin-top:18px}.project-empty{padding:40px 0;color:var(--muted)}.post-meta{margin-bottom:24px}.prose blockquote{border-left:3px solid var(--accent);padding:12px 24px;margin:25px 0}.prose li{margin:9px 0}.studio-contact{margin:30px 0}.hero h1,.page h1,.brand{overflow-wrap:anywhere}.site-footer{flex-wrap:wrap}.site-footer p{margin:0}`;}
function img(url,alt,cl){const src=safeUrl(url,true);return src?`<img class="${cl}" src="${esc(src)}" alt="${esc(alt)}" />`:'';}
function nav(p,preview){return `<nav class="site-nav">${p.menu.map(item=>{const entry=p.entries.find(e=>e.id===item.target);const url=item.target==='home'?'/':item.target==='404'?'/404.html':entry?entryUrl(entry):safeUrl(item.url);if(!url)return '';return `<a href="${esc(url)}"${preview&&item.target!=='external'?` data-page="${esc(item.target)}"`:''}>${esc(item.label)}</a>`;}).join('')}</nav>`;}
function linkFor(p,id,preview){const e=p.entries.find(e=>e.id===id);return `href="${esc(e?entryUrl(e):id==='404'?'/404.html':'/')}"${preview?` data-page="${esc(e||id==='404'?id:'home')}"`:''}`;}
function hero(p,preview){return layoutHero(p,{image:img(p.heroImage,p.heroAlt,'hero-img'),button:p.heroButton?`<a class="pill" ${linkFor(p,p.heroTarget,preview)}>${esc(p.heroButton)} &#8599;</a>`:''});}
function collection(p,preview){const cards=p.entries.filter(e=>e.kind!=='page'&&e.published).map(e=>`<article class="layout-card"><a ${linkFor(p,e.id,preview)}><figure>${img(e.image,e.alt,'story-img')}</figure><div class="entry-copy"><span class="eyebrow">${esc(e.category)}</span><h3>${esc(e.title)}</h3><p>${esc(e.excerpt)}</p>${e.kind==='product'?`<p class="price">${esc(e.price)}</p>`:''}<span class="entry-action">${p.language==='pl'?'Zobacz więcej':'Explore'} &#8599;</span></div></a></article>`).join('');return layoutCollection(p,cards,nav(p,preview));}
function bloggerCollection(p){return layoutCollection(p,`<b:loop values="data:posts" var="post"><article class="layout-card"><a expr:href="data:post.url"><figure><b:if cond="data:post.firstImageUrl"><img expr:src="data:post.firstImageUrl" expr:alt="data:post.title" loading="lazy"/></b:if></figure><div class="entry-copy"><span class="eyebrow"><data:post.timestamp/></span><h3><data:post.title/></h3><p><data:post.snippet/></p><span class="entry-action">${p.language==='pl'?'Zobacz więcej':'Explore'} &#8599;</span></div></a></article></b:loop>`,nav(p,false));}

function sections(p){return p.sections.map(s=>`<section class="extra-section"><div class="${s.type==='image'?'':'prose'}">${s.title?`<h2>${esc(s.title)}</h2>`:''}${s.type==='image'?img(s.image,s.alt,'page-image'):''}${richText(s.body)}${s.type==='cta'&&safeUrl(s.url)?`<a class="pill" href="${esc(safeUrl(s.url))}">${esc(s.button)}</a>`:''}</div></section>`).join('');}
export function entryContent(entry,p,title=true){const pl=p.language==='pl';return `<article class="page entry-layout-${p.siteLayout} ${entry.kind==='product'?'detail':''}">${entry.kind==='product'?img(entry.image,entry.alt,'product-image'):''}<div class="${entry.kind==='product'?'':'prose'}"><span class="eyebrow">${esc(entry.category)}</span>${title?`<h1>${esc(entry.title)}</h1>`:''}${entry.author?`<p class="post-meta">${esc(entry.author)}</p>`:''}<p>${esc(entry.excerpt)}</p>${entry.kind!=='product'?img(entry.image,entry.alt,'page-image'):''}${entry.kind==='product'?`<p class="price">${esc(entry.price)}</p>`:''}${richText(entry.body)}${entry.kind==='product'||entry.id==='contact'?`<p class="studio-contact"><a class="pill" href="mailto:${esc(base.config({},options(p)).email)}">${pl?'Napisz do nas':'Get in touch'} · ${esc(base.config({},options(p)).email)}</a></p>`:''}</div></article>`;}
function main(p,page,preview){if(page==='home')return hero(p,preview)+sections(p)+(p.showPosts?collection(p,preview):'');const e=p.entries.find(e=>e.id===page);if(e)return entryContent(e,p);return `<section class="error"><strong>404</strong><h1>${esc(p.errorTitle)}</h1><p>${esc(p.errorText)}</p><a class="pill" href="/"${preview?' data-page="home"':''}>${p.language==='pl'?'Wróć na stronę główną':'Back home'}</a></section>`;}
function footer(p){return `<footer class="site-footer"><span>© ${esc(p.brand)}</span><p>${esc(p.footer)}</p></footer>`;}
export function renderPreview(t,page='home',l='pl',o={}){const p=project(t,o,l);if(!p)return base.renderPreview(t,page,l,o);let html=base.renderPreview(resolve(t,p),'home',p.language,options(p));html=html.replace(/<header class="site-header">[\s\S]*?<\/header>/,()=>layoutHeader(p,nav(p,true))).replace(/<main>[\s\S]*?<\/main>/,()=>`<main>${main(p,page,true)}</main>`).replace(/<footer class="site-footer">[\s\S]*?<\/footer>/,()=>footer(p)).replace('</style>',()=>css(p)+layoutCss+'</style>');return html;}
export function renderBlogger(t,l='pl',o={}){const p=project(t,o,l);if(!p)return base.renderBlogger(t,l,o);let xml=base.renderBlogger(resolve(t,p),p.language,options(p));xml=xml.replace(/<header class="site-header">[\s\S]*?<\/header>/,()=>layoutHeader(p,nav(p,false))).replace(/<b:if cond='data:blog.url == data:blog.homepageUrl'>[\s\S]*?<\/b:if>/,()=>`<b:if cond='data:blog.url == data:blog.homepageUrl'>${hero(p,false)}${sections(p)}</b:if>`).replace(/<section class="error">[\s\S]*?<\/section>/,()=>main(p,'404',false)).replace(/<footer class="site-footer">[\s\S]*?<\/footer>/,()=>footer(p)).replace(']]></b:skin>',()=>css(p)+layoutCss+']]></b:skin>');xml=xml.replace('<article class="page">',`<article class="page entry-layout-${p.siteLayout}">`).replace(/<div class="post-list"><b:loop[\s\S]*?<\/b:loop><\/div>/,()=>p.showPosts?bloggerCollection(p):`<b:if cond='data:blog.url != data:blog.homepageUrl'>${bloggerCollection(p)}</b:if>`);return xml;}
export function packageFiles(t,l='pl',o={}){const p=project(t,o,l);if(!p)return base.packageFiles(t,l,o);const files={'theme.xml':renderBlogger(t,l,o),'project.forma.json':JSON.stringify(p,null,2)};const manifest=[];for(const e of p.entries){files[entryPath(e)]=entryContent(e,p,e.kind==='page');manifest.push({title:e.title,kind:e.kind,category:e.category,status:e.published?'ready':'draft',file:entryPath(e),suggestedPageSlug:e.kind==='page'?slugFor(e):null,existingUrl:e.url||null});}for(const page of ['home',...p.entries.map(e=>e.id),'404'])files[`preview/${page}.html`]=renderPreview(t,page,l,o).replace(/<script>[\s\S]*?<\/script>/,'').replace(/href="[^"]*" data-page="([^"]+)"/g,'href="$1.html"');files['content-manifest.json']=JSON.stringify(manifest,null,2);files['INSTALL.txt']=p.language==='pl'?`FORMA THEMES — ${p.brand}\n\n1. Zrób kopię starego motywu Bloggera. W Motyw → Edytuj HTML wklej theme.xml.\n2. Otwórz content-manifest.json: zawiera tytuły i pliki wszystkich Twoich artykułów, ofert oraz stron, także szkiców.\n3. Artykuły i oferty dodaj jako Wpisy w Bloggerze. Wpisz tytuł z manifestu, przełącz edytor na HTML i wklej odpowiedni plik content/. Szkice zapisz bez publikowania.\n4. Podstrony dodaj w Strony, wklejając HTML z pages/. Użyj sugerowanego sluga jako pierwszego tytułu, aby uzyskać oczekiwany adres. Po publikacji zmień wyświetlany tytuł.\n5. Sprawdź rzeczywiste adresy. W edytorze Forma możesz wpisać adres wpisu lub strony w pole URL, a następnie ponownie wyeksportować theme.xml. Dopóki wpis nie ma URL, link prowadzi do wyszukiwania jego tytułu.\n6. Strona główna Bloggera wyświetla faktycznie opublikowane wpisy. Sam XML motywu NIE tworzy wpisów ani stron.\n7. Podgląd offline: otwórz preview/home.html. Projekt do dalszej edycji: zaimportuj project.forma.json w Dostosuj → Projekt.\n8. Publikacja wymaga własnego poprawnego e-maila i zdjęć dostępnych przez HTTP(S). Sprawdź motyw na testowym Bloggerze.\n\nTen pakiet nie publikuje automatycznie na Twoim koncie.\n`:`FORMA THEMES — ${p.brand}\n\n1. Back up your Blogger theme, then paste theme.xml into Theme → Edit HTML.\n2. content-manifest.json lists your posts, offers and pages, including drafts.\n3. Create Blogger posts with the titles in the manifest and paste the matching content/ file in HTML view. Keep drafts unpublished.\n4. Create Blogger pages with pages/ HTML. Use the suggested slug as the first title, then rename after publication.\n5. Verify actual URLs. Enter them in the Forma editor and export theme.xml again. Posts without a URL link to a title search.\n6. The Blogger homepage lists actual published posts. Theme XML does NOT create posts or pages.\n7. Open preview/home.html for the offline preview. Import project.forma.json in Customize → Project to continue editing.\n8. Set your real contact email and HTTP(S) image URLs. Test on a Blogger test site.\n\nThis package does not publish to your account automatically.\n`;return files;}
